using System;
using System.Collections.Generic;
using System.Linq;
namespace MaritimeLegend.Domain {
public partial class GameService : IMarketService,IProductionService {
        public void Log(string text){S.journal.Insert(0,text);if(S.journal.Count>C.balance.events.journalLimit)S.journal.RemoveAt(S.journal.Count-1);}
        public void Emit(string trigger){foreach(var e in C.events.Where(x=>x.trigger==trigger).OrderByDescending(x=>x.priority)){if(S.eventFlags.Contains(e.id)||!e.prerequisites.All(S.eventFlags.Contains))continue;S.eventFlags.Add(e.id);S.pendingEvents.Add(e.id);foreach(var effect in e.effects)if(effect.type=="gold")S.gold+=effect.value;Log(e.title+"："+e.dialogue);}}
        public string ChooseEvent(bool support){if(S.pendingEvents.Count==0)return "没有待处理事件";var id=S.pendingEvents[0];if(support){if(S.gold<C.balance.events.supportPrice)return "金币不足，需要"+C.balance.events.supportPrice+"金币支援港口";S.gold-=C.balance.events.supportPrice;S.cities[S.city].reputation+=C.balance.events.supportReputation;Gain(C.balance.skills.reputationSkill,C.balance.events.supportExperience);Log("选择支援港口："+C.balance.events.supportPrice+"金币换得"+C.balance.events.supportReputation+"声望。");}S.pendingEvents.RemoveAt(0);return support?"已支援港口，声望+"+C.balance.events.supportReputation:"已记录事件";}
        public void CheckQuest(){if(S.chapter==C.balance.quests.firstChapter&&S.trades>0&&S.produced>0&&S.routes.Count>0){S.chapter=C.balance.quests.secondChapter;S.gold+=C.balance.quests.chapterTwoReward;Log("第二章：诸港的契约。商会授予"+C.balance.quests.chapterTwoReward+"金币发展金。");}if(S.chapter==C.balance.quests.secondChapter&&S.cities.Count(x=>x.license)>=C.balance.quests.licensedCitiesRequired&&S.partners.Any(x=>x.active)&&S.produced>=C.balance.quests.productionOrdersRequired){S.chapter=C.balance.quests.finalChapter;S.gold+=C.balance.quests.chapterThreeReward;Log("第三章：世界之环。诸港联合提供"+C.balance.quests.chapterThreeReward+"金币远航资金。");}}
        public string SubmitMaterials(){if(S.materialsSubmitted)return "材料已经提交，无须重复交付";if(S.chapter<C.balance.quests.finalChapter)return "第三章开放此挑战";var wood=C.objectives.materialOne;var cloth=C.objectives.materialTwo;var a=S.cargo.batches.FirstOrDefault(x=>x.product==wood&&x.quantity>=C.balance.quests.materialQuantity&&x.quality<=C.balance.quests.materialQuality);var b=S.cargo.batches.FirstOrDefault(x=>x.product==cloth&&x.quantity>=C.balance.quests.materialQuantity&&x.quality<=C.balance.quests.materialQuality&&a!=null&&x.origin!=a.origin);if(a==null||b==null)return "船舱需要来自不同港口的品质2以上木板、布匹各1（可在不同港制造）";a.quantity-=C.balance.quests.materialQuantity;b.quantity-=C.balance.quests.materialQuantity;S.cargo.batches.RemoveAll(x=>x.quantity==0);S.materialsSubmitted=true;return "两港高品质材料已登记并交付";}
        public string BeginFinal(){if(S.ended)return "传奇航路已经建立，可继续自由经营";if(S.chapter<C.balance.quests.finalChapter||S.routes.Count<C.balance.quests.finalRoutesRequired||!S.materialsSubmitted||!S.instrumentMade||!S.sailsMade||S.ships[0].type==C.balance.quests.startingShipType)return "尚未满足最终挑战条件，查看任务面板";if(!S.partners.Any(x=>x.active&&x.trust>=C.balance.quests.finalPartnerTrust))return "需要一位信赖2级的当班伙伴";if(S.city==C.balance.quests.finalPort)return "请从杭州以外的港口启程";S.finalVoyage=true;Emit("final");return Depart(C.balance.quests.finalPort);}
        public void Finish(){if(S.ended)return;S.ended=true;S.finalVoyage=false;S.finalStage=C.balance.quests.completedStage;S.gold+=C.balance.quests.endingReward;Log("传奇航路建立。你的家族把诸港连接成一张共同的海图。所有伙伴的远航故事仍将继续。");}
}}
